});

test('VIP20 nao aplicavel para cliente regular', () => {
  assert.deepEqual(resolveCoupon('VIP20', { orders: 9, tier: 'regular' }, false), { code: 'VIP20', status: 'not-eligible', percent: 0 });
});

test('cupom desconhecido nao aplicavel', () => {
  assert.deepEqual(resolveCoupon('BLACKFRIDAY', { orders: 0, tier: 'vip' }, false), { code: 'BLACKFRIDAY', status: 'not-eligible', percent: 0 });
  assert.deepEqual(resolveCoupon('toString', { orders: 0, tier: 'vip' }, false), { code: 'toString', status: 'not-eligible', percent: 0 });
});

test('codigo de cupom em minusculas nao aplicavel', () => {
  assert.deepEqual(resolveCoupon('vip20', { orders: 9, tier: 'vip' }, false), { code: 'vip20', status: 'not-eligible', percent: 0 });
});

test('cupom sem cliente nao aplicavel', () => {
  assert.deepEqual(resolveCoupon('WELCOME10', undefined, false), { code: 'WELCOME10', status: 'not-eligible', percent: 0 });
});

test('cupom nao acumula com volume', () => {
  assert.deepEqual(resolveCoupon('VIP20', { orders: 9, tier: 'vip' }, true), { code: 'VIP20', status: 'not-stackable', percent: 0 });
