// Testes unitários das funções puras de src/discounts.js (nomes distintos dos cenários).

test('discountedLine devolve o valor cheio abaixo de 10 unidades', () => {
  assert.deepEqual(discountedLine(item('A', 5, 9)), { amount: 45, volume: false });
});

test('discountedLine tira 10 por cento a partir de 10 unidades', () => {
  assert.deepEqual(discountedLine(item('A', 3, 10)), { amount: 27, volume: true });
});

test('hasVolumeDiscount detecta qualquer linha com 10 unidades ou mais', () => {
  assert.equal(hasVolumeDiscount([item('A', 1, 9), item('B', 1, 1)]), false);
  assert.equal(hasVolumeDiscount([item('A', 1, 9), item('B', 1, 10)]), true);
});

test('evaluateCoupon sem cupom ou com cupom vazio devolve none', () => {
  const none = { status: 'none', code: undefined, rate: 0, percent: 0 };
  assert.deepEqual(evaluateCoupon({ customer: { orders: 0 } }, false), none);
  assert.deepEqual(evaluateCoupon({ coupon: '', customer: { orders: 0 } }, false), { ...none, code: '' });
});

test('evaluateCoupon com volume devolve not-stackable', () => {
  assert.deepEqual(evaluateCoupon({ coupon: 'VIP20', customer: { tier: 'vip' } }, true), { status: 'not-stackable', code: 'VIP20', rate: 0, percent: 0 });
});

test('evaluateCoupon aplica WELCOME10 e VIP20 para cliente elegivel', () => {
  assert.deepEqual(evaluateCoupon({ coupon: 'WELCOME10', customer: { orders: 0 } }, false), { status: 'applied', code: 'WELCOME10', rate: 0.1, percent: 10 });
  assert.deepEqual(evaluateCoupon({ coupon: 'VIP20', customer: { tier: 'vip' } }, false), { status: 'applied', code: 'VIP20', rate: 0.2, percent: 20 });
});

test('evaluateCoupon recusa cupom desconhecido, cliente inelegivel ou ausente', () => {
  const notApplicable = (code) => ({ status: 'not-applicable', code, rate: 0, percent: 0 });
  assert.deepEqual(evaluateCoupon({ coupon: 'welcome10', customer: { orders: 0 } }, false), notApplicable('welcome10'));
  assert.deepEqual(evaluateCoupon({ coupon: 'WELCOME10', customer: { orders: 1 } }, false), notApplicable('WELCOME10'));
  assert.deepEqual(evaluateCoupon({ coupon: 'VIP20' }, false), notApplicable('VIP20'));
  assert.deepEqual(evaluateCoupon({ coupon: 'toString', customer: { orders: 0 } }, false), notApplicable('toString'));
});

test('couponDiscount multiplica o subtotal pela taxa so quando aplicado', () => {
  assert.equal(couponDiscount(2.0999999999999996, { status: 'applied', rate: 0.1 }), 0.20999999999999996);
  assert.equal(couponDiscount(100, { status: 'not-applicable', rate: 0 }), 0);
});

test('tabela COUPONS e suas entradas sao congeladas', () => {
  assert.ok(Object.isFrozen(COUPONS));
  assert.ok(Object.values(COUPONS).every((coupon) => Object.isFrozen(coupon)));
});

test('funcoes de desconto nao alteram os argumentos', () => {
  const order = { coupon: 'WELCOME10', customer: { orders: 0 }, items: [item('A', 3, 10)] };
  const snapshot = structuredClone(order);

  discountedLine(order.items[0]);
  hasVolumeDiscount(order.items);
  couponDiscount(27, evaluateCoupon(order, false));

  assert.deepEqual(order, snapshot);
});
